package com.treadz.console.programs.model

/**
 * Training program model: one immutable model for the three kinds of program.
 *
 *  - [ProgramKind.Standard]: shipped in the app's code as a relative template (percentages of an intensity range that
 *    the user picks when starting).
 *  - [ProgramKind.Free]: written by the user, absolute values by default.
 *  - [ProgramKind.Personalised]: generated by the app from the user's data and stored already generated, together with
 *    the generator metadata ([ProgramOrigin]).
 *
 * A program is never executed directly: it is first resolved into a concrete plan (see
 * `com.treadz.console.programs.plan.ProgramResolver`). The model classes do not check themselves on construction so
 * that an editor can hold a half-written program; use [ProgramValidator] before storing or resolving one.
 */
data class Program(
    /** Stable identifier: UUID text, or a `standard-...` slug for the standard programs shipped in the app. */
    val id: String,
    val name: String,
    val kind: ProgramKind,
    val steps: List<ProgramStep>,
    val description: String? = null,
    /** Only for [ProgramKind.Personalised]: what generated the program. */
    val origin: ProgramOrigin? = null,
    /**
     * Version of the document format this program was written with. By default the lowest version that can hold it
     * ([schemaVersionFor]): 1, or 2 when a block keeps a value (see [BlockTarget.Absolute]).
     */
    val schemaVersion: Int = schemaVersionFor(steps),
) {
    /** Number of blocks once every [Repeat] is expanded. */
    val expandedBlockCount: Int
        get() = steps.sumOf { step ->
            when (step) {
                is Block -> 1
                is Repeat -> step.count.toLong() * step.blocks.size
            }
        }.coerceAtMost(Int.MAX_VALUE.toLong()).toInt()

    /** True when some block leaves a speed or an incline empty ("keep"; see [BlockTarget.Absolute]). */
    val usesKeep: Boolean get() = usesKeep(steps)

    /** The first block a run executes (the first block of the first repeat when the program starts with one). */
    val firstBlock: Block?
        get() = when (val first = steps.firstOrNull()) {
            is Block -> first
            is Repeat -> first.blocks.firstOrNull()
            null -> null
        }

    companion object {
        /** Newest version of the JSON document format this code reads and writes. */
        const val SCHEMA_VERSION = 2

        /** Version of every document that does not use a newer feature. Version 2 adds "keep" values. */
        const val BASE_SCHEMA_VERSION = 1

        /** The lowest format version that can hold a program with these [steps]. */
        fun schemaVersionFor(steps: List<ProgramStep>): Int = if (usesKeep(steps)) SCHEMA_VERSION else BASE_SCHEMA_VERSION

        private fun usesKeep(steps: List<ProgramStep>): Boolean = steps.any { step ->
            when (step) {
                is Block -> step.target.keepsSpeed || step.target.keepsIncline
                is Repeat -> step.blocks.any { it.target.keepsSpeed || it.target.keepsIncline }
            }
        }
    }
}

enum class ProgramKind { Standard, Free, Personalised }

/**
 * What produced a personalised program: the generator, its version and the inputs it used (profile, history…), as plain
 * text so the stored program can be explained and regenerated later.
 */
data class ProgramOrigin(
    val generatorId: String,
    val generatorVersion: Int,
    val inputs: Map<String, String> = emptyMap(),
)

/** A step of a program: a single [Block] or a [Repeat] of several blocks. Only one level of nesting exists. */
sealed interface ProgramStep

/** What the block is for. Used by the UI and for analysis; the engine treats all phases alike. */
enum class BlockPhase { WarmUp, Work, Recovery, CoolDown, Other }

/** One segment of the workout: it ends by time or by distance and has one [target]. */
data class Block(
    val phase: BlockPhase,
    val end: BlockEnd,
    val target: BlockTarget,
    /** Optional label ("4 min hard"). */
    val name: String? = null,
) : ProgramStep

/** [blocks] performed [count] times in a row. */
data class Repeat(val count: Int, val blocks: List<Block>) : ProgramStep

/** How a block ends. The treadmill's own time/distance countdowns are never used: the app keeps the clock. */
sealed interface BlockEnd {
    data class Duration(val seconds: Int) : BlockEnd
    data class Distance(val meters: Int) : BlockEnd
}

/** What a block asks of the treadmill. */
sealed interface BlockTarget {

    /**
     * The block starts with the speed that is in force when it begins (see [Absolute]). Always false for targets that
     * cannot keep.
     */
    val keepsSpeed: Boolean get() = false

    /** The block starts with the incline that is in force when it begins (see [Absolute]). */
    val keepsIncline: Boolean get() = false

    /** Fixed speed and incline, known when the program is written. */
    sealed interface Fixed : BlockTarget

    /**
     * Speed in km/h and incline in %. Either one may be `null`, which means **keep**: the block starts with the value
     * the treadmill has at that moment, i.e. the one in force at the end of the previous block (manual changes from the
     * app or the console and the last heart-rate adjustment included). Because of that the first block a run executes
     * cannot keep anything (see [ProgramValidator]).
     *
     * For [HeartRate.start], a `null` quantity that the control adjusts starts from the value in force, brought within
     * the block's bounds; a `null` quantity that it does not adjust is simply kept.
     */
    data class Absolute(val speedKmh: Double?, val inclinePercent: Double?) : Fixed {
        override val keepsSpeed: Boolean get() = speedKmh == null
        override val keepsIncline: Boolean get() = inclinePercent == null
    }

    /**
     * Speed and incline as a percentage (0-100) of the ranges chosen when the program starts: speed 0 % is the easy
     * speed and 100 % the maximum speed; incline 0 % is flat and 100 % the maximum incline.
     */
    data class Relative(val speedPercent: Double, val inclinePercent: Double) : Fixed

    /**
     * Keep the heart rate inside [zone] by adjusting [adjust] between [minimum] and [maximum], starting from [start].
     * The bounds are in the same scale as [start] (km/h or % for an absolute start; % of the range for a relative one)
     * and apply to the adjusted quantity. The program runner does the control (see `ProgramRunner` and
     * `HeartRateBlockControl` for the rules).
     */
    data class HeartRate(
        val zone: HeartRateZone,
        val adjust: HeartRateAdjust,
        val minimum: Double,
        val maximum: Double,
        val start: Fixed,
    ) : BlockTarget {
        override val keepsSpeed: Boolean get() = start.keepsSpeed
        override val keepsIncline: Boolean get() = start.keepsIncline
    }
}

/**
 * Target zone, as a percentage of [basis].
 *
 * @property profileZone When set (1-5), the target is that zone of the **user's own zones** (from their thresholds or
 *   level), converted to bpm when the session runs with the zones in force then (see `HeartRateProfile.zones`). The
 *   percentages are then the standard zone of the same number, used when the user's zones are not known; an app that
 *   does not know the field reads them as a plain zone.
 */
data class HeartRateZone(val basis: HeartRateBasis, val lowPercent: Int, val highPercent: Int, val profileZone: Int? = null) {
    companion object {
        /** Zone [number] (1-5) of the user's zones, with the standard percentages of the same zone as fallback. */
        fun ofProfile(number: Int): HeartRateZone {
            require(number in 1..5) { "profile zone must be 1-5 (was $number)" }
            val low = 40 + number * 10
            return HeartRateZone(HeartRateBasis.MaxHeartRate, low, low + 10, profileZone = number)
        }
    }
}

enum class HeartRateBasis { MaxHeartRate, HeartRateReserve }

/** Which quantity the heart-rate control moves. */
enum class HeartRateAdjust { Speed, Incline }
